import {
  failedRequest,
  pendingRequest,
  succeededRequest,
} from '@shared/state/request/request-state.transitions';
import { authRootState } from '../../testing/auth-state.fixtures';
import { authError, TEST_USER, validSession } from '../../testing/auth.fixtures';
import { authFeature } from './auth.feature';

/** Only derived selectors are tested; the top-level ones are generated by `createFeature`. */
describe('authFeature extra selectors', () => {
  describe('session', () => {
    it('derives authentication from the presence of a session', () => {
      expect(authFeature.selectIsAuthenticated(authRootState())).toBe(false);
      expect(authFeature.selectIsAuthenticated(authRootState({ session: validSession() }))).toBe(
        true,
      );
    });

    it('exposes the access token of the current session', () => {
      expect(authFeature.selectAccessToken(authRootState())).toBeNull();
      expect(authFeature.selectAccessToken(authRootState({ session: validSession() }))).toBe(
        'access',
      );
    });
  });

  describe('user', () => {
    it('composes the full name of the current user', () => {
      expect(authFeature.selectUserFullName(authRootState())).toBeNull();
      expect(authFeature.selectUserFullName(authRootState({ user: TEST_USER }))).toBe(
        'Ada Lovelace',
      );
    });

    it('trims a missing name part', () => {
      const user = { ...TEST_USER, lastName: '' };

      expect(authFeature.selectUserFullName(authRootState({ user }))).toBe('Ada');
    });
  });

  describe('loading statuses', () => {
    it('are all false in the initial state', () => {
      const state = authRootState();

      expect(authFeature.selectIsLoggingIn(state)).toBe(false);
      expect(authFeature.selectIsRegistering(state)).toBe(false);
      expect(authFeature.selectIsRestoringSession(state)).toBe(false);
      expect(authFeature.selectIsLoadingCurrentUser(state)).toBe(false);
    });

    it('track each operation independently so several can be pending at once', () => {
      const state = authRootState({
        loginRequest: succeededRequest(),
        sessionRestoreRequest: pendingRequest(),
        currentUserRequest: pendingRequest(),
      });

      expect(authFeature.selectIsLoggingIn(state)).toBe(false);
      expect(authFeature.selectIsRegistering(state)).toBe(false);
      expect(authFeature.selectIsRestoringSession(state)).toBe(true);
      expect(authFeature.selectIsLoadingCurrentUser(state)).toBe(true);
    });
  });

  describe('error statuses', () => {
    it('are all null in the initial state', () => {
      const state = authRootState();

      expect(authFeature.selectLoginError(state)).toBeNull();
      expect(authFeature.selectRegistrationError(state)).toBeNull();
      expect(authFeature.selectSessionRestoreError(state)).toBeNull();
      expect(authFeature.selectCurrentUserError(state)).toBeNull();
    });

    it('expose each operation error separately so they can coexist', () => {
      const loginError = authError('invalid-credentials');
      const userError = authError('network');
      const state = authRootState({
        loginRequest: failedRequest(loginError),
        currentUserRequest: failedRequest(userError),
      });

      expect(authFeature.selectLoginError(state)).toEqual(loginError);
      expect(authFeature.selectCurrentUserError(state)).toEqual(userError);
      expect(authFeature.selectRegistrationError(state)).toBeNull();
      expect(authFeature.selectSessionRestoreError(state)).toBeNull();
    });
  });
});
